/**
 * @file Drizzle schema for companies, memberships, invitations and
 * invite links. Invitations and invite links without a company are for
 * joining the staff (staff roles live on `user.platform_role`).
 *
 * Conventions: every ID is a time-ordered UUIDv7 generated by Postgres (no
 * auto-increment), every foreign key has an index, and timestamps are stored
 * with time zone.
 */
import { sql } from 'drizzle-orm';
import { check, index, pgEnum, pgTable, text, uniqueIndex, uuid } from 'drizzle-orm/pg-core';

import { COMPANY_ROLES, PLATFORM_ROLES, ROLE_IDS } from '../../lib/authz/roles';
import { DEFAULT_LOCALE, LOCALES } from '../../lib/i18n/locales';
import { user } from './auth';
import { createdAt, id, oneOf, timestampTz } from './columns';

/** Roles in a company; see `src/lib/authz/roles.ts`. */
export const companyRole = pgEnum('company_role', COMPANY_ROLES);

/** Roles an invitation or invite link can give: company roles, or platform roles for staff. */
export const inviteRole = pgEnum('invite_role', ROLE_IDS);

/** The platform roles as an SQL list, for the checks below. */
const platformRoleList = sql.raw(PLATFORM_ROLES.map((role) => `'${role}'`).join(', '));

/** Companies, registered by the staff. */
export const company = pgTable(
  'company',
  {
    id: id(),
    name: text('name').notNull(),
    /** URL-friendly unique name. */
    slug: text('slug').notNull().unique(),
    /** Set while the company is deactivated; its members then lose access. */
    deactivatedAt: timestampTz('deactivated_at'),
    createdBy: uuid('created_by').references(() => user.id, { onDelete: 'set null' }),
    createdAt: createdAt(),
  },
  (table) => [index('company_created_by_idx').on(table.createdBy)],
);

/** A user's role in a company. Users can belong to several companies. */
export const membership = pgTable(
  'membership',
  {
    id: id(),
    companyId: uuid('company_id')
      .notNull()
      .references(() => company.id, { onDelete: 'cascade' }),
    userId: uuid('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    role: companyRole('role').notNull(),
    createdAt: createdAt(),
  },
  (table) => [
    /** One membership per user per company; also serves lookups by company. */
    uniqueIndex('membership_company_user_idx').on(table.companyId, table.userId),
    index('membership_user_idx').on(table.userId),
  ],
);

/**
 * An emailed invitation to join a company, or staff when `company_id` is
 * empty, with a role.
 */
export const invitation = pgTable(
  'invitation',
  {
    id: id(),
    /** The company to join, or `null` to join the staff. */
    companyId: uuid('company_id').references(() => company.id, { onDelete: 'cascade' }),
    /** Lower-cased email address the invitation was sent to. */
    email: text('email').notNull(),
    /** A company role for a company, a platform role for staff. */
    role: inviteRole('role').notNull(),
    /** SHA-256 hash of the secret token in the invitation link. */
    tokenHash: text('token_hash').notNull().unique(),
    invitedBy: uuid('invited_by').references(() => user.id, { onDelete: 'set null' }),
    expiresAt: timestampTz('expires_at').notNull(),
    acceptedAt: timestampTz('accepted_at'),
    revokedAt: timestampTz('revoked_at'),
    /** When the "expires soon" reminder was sent, so it's sent only once. */
    reminderSentAt: timestampTz('reminder_sent_at'),
    /**
     * Since when a run of the reminder job holds the invitation to send its
     * reminder, so two runs don't both send it; empty again once the reminder
     * was sent or couldn't be. A claim that's still there after 15 minutes is
     * from a run that was stopped mid-send, and the next run takes it again.
     */
    reminderClaimedAt: timestampTz('reminder_claimed_at'),
    /**
     * The language the invitation, its resends and its reminder are written
     * in (an invitee who has an account gets their own language instead).
     */
    locale: text('locale', { enum: LOCALES }).notNull().default(DEFAULT_LOCALE),
    createdAt: createdAt(),
  },
  (table) => [
    index('invitation_company_idx').on(table.companyId),
    index('invitation_email_idx').on(table.email),
    index('invitation_invited_by_idx').on(table.invitedBy),
    /** At most one open invitation per email per company... */
    uniqueIndex('invitation_open_company_email_idx')
      .on(table.companyId, table.email)
      .where(
        sql`${table.companyId} is not null and ${table.acceptedAt} is null and ${table.revokedAt} is null`,
      ),
    /** ...and to the staff. */
    uniqueIndex('invitation_open_staff_email_idx')
      .on(table.email)
      .where(
        sql`${table.companyId} is null and ${table.acceptedAt} is null and ${table.revokedAt} is null`,
      ),
    /** Staff invitations give platform roles; company invitations give company roles. */
    check(
      'invitation_role_fits_target',
      sql`(${table.companyId} is null) = (${table.role} in (${platformRoleList}))`,
    ),
    oneOf('invitation_locale_valid', table.locale, LOCALES),
  ],
);

/**
 * A single-use invite link to a company, or staff when `company_id` is
 * empty. Whoever opens it first enters their email, which turns the link into
 * a normal invitation for that address.
 */
export const inviteLink = pgTable(
  'invite_link',
  {
    id: id(),
    /** The company to join, or `null` to join the staff. */
    companyId: uuid('company_id').references(() => company.id, { onDelete: 'cascade' }),
    /** A company role for a company, a platform role for staff. */
    role: inviteRole('role').notNull(),
    /** SHA-256 hash of the secret token in the link. */
    tokenHash: text('token_hash').notNull().unique(),
    createdBy: uuid('created_by').references(() => user.id, { onDelete: 'set null' }),
    expiresAt: timestampTz('expires_at').notNull(),
    /** When the link was used up. */
    usedAt: timestampTz('used_at'),
    /** Lower-cased email entered when the link was used. */
    usedByEmail: text('used_by_email'),
    /** The invitation the link turned into. */
    invitationId: uuid('invitation_id').references(() => invitation.id, { onDelete: 'set null' }),
    revokedAt: timestampTz('revoked_at'),
    createdAt: createdAt(),
  },
  (table) => [
    index('invite_link_company_idx').on(table.companyId),
    index('invite_link_created_by_idx').on(table.createdBy),
    index('invite_link_invitation_idx').on(table.invitationId),
    /** Staff links give platform roles; company links give company roles. */
    check(
      'invite_link_role_fits_target',
      sql`(${table.companyId} is null) = (${table.role} in (${platformRoleList}))`,
    ),
  ],
);
